"""The README demo is generated by executing the actual CLI."""

import subprocess
import sys
import xml.etree.ElementTree as ET
from pathlib import Path


def test_demo_generator_runs_cli_and_writes_accessible_svg(tmp_path):
    root = Path(__file__).resolve().parents[1]
    result = subprocess.run(
        [sys.executable, str(root / "docs/generate_demo.py"), "--output-dir", str(tmp_path)],
        # Match the documented checkout workflow so pytest-cov 5 can find
        # pyproject.toml before subprocess startup; output still goes to tmp_path.
        cwd=root,
        capture_output=True,
        text=True,
    )
    assert result.returncode == 0, result.stderr
    transcript = (tmp_path / "demo.txt").read_text(encoding="utf-8")
    assert "Found 2 differences:" in transcript
    assert "users[0].role" in transcript
    assert "users[1]" in transcript
    assert "Exit code: 1 (differences found)" in transcript
    svg = ET.parse(tmp_path / "demo.svg").getroot()
    assert svg.attrib["role"] == "img"
    assert svg.find("{http://www.w3.org/2000/svg}title") is not None
    assert svg.find("{http://www.w3.org/2000/svg}desc") is not None
    assert not svg.findall(".//{http://www.w3.org/2000/svg}script")
    assert not svg.findall(".//{http://www.w3.org/2000/svg}image")
